"""Fixed-width text column formatter."""


def wrap_words(text, width):
    """Wrap text into lines of at most `width` characters, breaking on spaces.

    A word longer than `width` is placed on its own line rather than split.
    """
    words = text.split()
    lines = []
    current = ""
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) < width:
            current = current + " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def format_table(rows, width):
    """Render rows as a table whose cells are wrapped to `width`."""
    out = []
    for row in rows:
        wrapped = [wrap_words(cell, width) for cell in row]
        height = max(len(cell) for cell in wrapped)
        for index in range(height):
            parts = []
            for cell in wrapped:
                parts.append(cell[index] if index < len(cell) else "")
            out.append(" | ".join(part.ljust(width) for part in parts))
    return out

import unittest

from textwrap_util import format_table, wrap_words


class WrapWordsTests(unittest.TestCase):
    def test_exact_width_line_is_kept_whole(self):
        # "ab cd" is exactly 5 characters and must fit on one line of width 5.
        self.assertEqual(["ab cd"], wrap_words("ab cd", 5))

    def test_wraps_when_over_width(self):
        self.assertEqual(["ab", "cde"], wrap_words("ab cde", 4))

    def test_long_word_is_not_split(self):
        self.assertEqual(["short", "enormouslylong"], wrap_words("short enormouslylong", 6))

    def test_empty_text(self):
        self.assertEqual([], wrap_words("", 5))


class FormatTableTests(unittest.TestCase):
    def test_single_row(self):
        self.assertEqual(["ab    | cd    "], format_table([["ab", "cd"]], 6))

    def test_empty_rows(self):
        self.assertEqual([], format_table([], 6))


if __name__ == "__main__":
    unittest.main()

